 "Corregir": "Verbeteren",
 "<b style=\"font-size:25px;color:#5ed3b0\">Corregir</b><br><span style=\"font-size:21px;color:#eef1fa\">Revisar un texto propio y explicar los fallos.</span>": "<b style=\"font-size:25px;color:#5ed3b0\">Verbeteren</b><br><span style=\"font-size:21px;color:#eef1fa\">Een eigen tekst nalopen en de fouten uitleggen.</span>",
 "Explicar": "Uitleggen",
